-- Sales-In ledger import — SALES CEBU.xlsx
-- 59 daily sheets (2026-09-07 to 2026-11-14): 561 sales, 832 line items,
-- 237 customers, 56,459,750 total.
-- Re-running is safe: sales are keyed by (branch_id, import_key) and skipped if already present.
-- Stock movements are intentionally NOT written for these historical sales.

begin;

alter table public.sales add column if not exists import_key text;
alter table public.sale_items add column if not exists source_description text;

create unique index if not exists sales_branch_import_key_idx
  on public.sales (branch_id, import_key)
  where import_key is not null;

insert into public.varieties (name, origin)
values
  ('Camel India', 'imported'),
  ('Super Mama India', 'imported'),
  ('Mama''s Best', 'local'),
  ('Jasmine', 'local'),
  ('Sweet Daisy', 'local'),
  ('Bambin', 'imported'),
  ('Eskaya', 'local'),
  ('Buko Pandan', 'local'),
  ('Used Empty Sacks', 'local')
on conflict (name) do nothing;

insert into public.skus (variety_id, sack_size, barcode)
select v.id, s.sack_size, s.barcode
from (values
  ('Camel India', 25, 'CAM-25KG'),
  ('Camel India', 50, 'CAM-50KG'),
  ('Super Mama India', 25, 'SM-25KG'),
  ('Super Mama India', 50, 'SM-50KG'),
  ('Mama''s Best', 5, 'MB-5KG'),
  ('Mama''s Best', 25, 'MB-25KG'),
  ('Mama''s Best', 50, 'MB-50KG'),
  ('Jasmine', 5, 'JAS-G-5KG'),
  ('Jasmine', 25, 'JAS-G-25KG'),
  ('Sweet Daisy', 25, 'SD-25KG'),
  ('Bambin', 25, 'BAM-25KG'),
  ('Eskaya', 25, 'ESK-25KG'),
  ('Eskaya', 50, 'ESK-50KG'),
  ('Buko Pandan', 25, 'BP-25KG'),
  ('Used Empty Sacks', 25, 'UES-25KG'),
  ('Used Empty Sacks', 50, 'UES-50KG')
) as s(variety_name, sack_size, barcode)
join public.varieties v on v.name = s.variety_name
on conflict (variety_id, sack_size) do nothing;

update public.skus sk
set barcode = s.barcode
from (values
  ('Camel India', 25, 'CAM-25KG'),
  ('Camel India', 50, 'CAM-50KG'),
  ('Super Mama India', 25, 'SM-25KG'),
  ('Super Mama India', 50, 'SM-50KG'),
  ('Mama''s Best', 5, 'MB-5KG'),
  ('Mama''s Best', 25, 'MB-25KG'),
  ('Mama''s Best', 50, 'MB-50KG'),
  ('Jasmine', 5, 'JAS-G-5KG'),
  ('Jasmine', 25, 'JAS-G-25KG'),
  ('Sweet Daisy', 25, 'SD-25KG'),
  ('Bambin', 25, 'BAM-25KG'),
  ('Eskaya', 25, 'ESK-25KG'),
  ('Eskaya', 50, 'ESK-50KG'),
  ('Buko Pandan', 25, 'BP-25KG'),
  ('Used Empty Sacks', 25, 'UES-25KG'),
  ('Used Empty Sacks', 50, 'UES-50KG')
) as s(variety_name, sack_size, barcode)
join public.varieties v on v.name = s.variety_name
where sk.variety_id = v.id
  and sk.sack_size = s.sack_size
  and (sk.barcode is null or sk.barcode = '');

insert into public.prices (sku_id, price, effective_from)
select sk.id, p.price, date '2026-11-14'
from (values
  ('KAS-25KG', 1280.00),
  ('JAP-25KG', 1160.00),
  ('MB-25KG', 1180.00),
  ('UES-50KG', 10.00),
  ('JAS-G-25KG', 1270.00),
  ('KAS-50KG', 1250.00),
  ('JAS-G-5KG', 270.00),
  ('CAM-25KG', 1000.00),
  ('UES-25KG', 3.00),
  ('BP-25KG', 1250.00),
  ('SM-50KG', 1900.00),
  ('MB-5KG', 260.00),
  ('SD-25KG', 1100.00),
  ('BAM-25KG', 1130.00),
  ('ESK-50KG', 2020.00),
  ('ESK-25KG', 2000.00),
  ('MB-50KG', 2360.00),
  ('CAM-50KG', 1900.00),
  ('SM-25KG', 1000.00)
) as p(barcode, price)
join public.skus sk on sk.barcode = p.barcode
where not exists (select 1 from public.prices pr where pr.sku_id = sk.id);

create or replace function public.import_sales_ledger(p_branch_id uuid, p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_row jsonb;
  v_item jsonb;
  v_sale uuid;
  v_customer uuid;
  v_sku uuid;
  v_name text;
  v_key text;
  v_method public.payment_method;
  v_total numeric;
  v_sales int := 0;
  v_items int := 0;
  v_skipped int := 0;
begin
  if not exists (select 1 from public.branches where id = p_branch_id) then
    raise exception 'Unknown branch %', p_branch_id;
  end if;

  for v_row in select * from jsonb_array_elements(p_rows)
  loop
    v_key := v_row->>'key';
    if v_key is null then continue; end if;

    select id into v_sale
    from public.sales
    where branch_id = p_branch_id and import_key = v_key and deleted_at is null;
    if v_sale is not null then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    v_name := nullif(btrim(coalesce(v_row->>'customer', '')), '');
    v_customer := null;
    if v_name is not null then
      select id into v_customer
      from public.customers
      where deleted_at is null
        and upper(btrim(name)) = upper(v_name)
        and (branch_id = p_branch_id or branch_id is null)
      order by (branch_id = p_branch_id) desc
      limit 1;
      if v_customer is null then
        insert into public.customers (branch_id, name)
        values (p_branch_id, v_name)
        returning id into v_customer;
      end if;
    end if;

    v_total := (v_row->>'total')::numeric;
    v_method := coalesce(nullif(v_row->>'method', '')::public.payment_method, 'cash');

    insert into public.sales (
      branch_id, customer_id, sale_date, status, payment_type,
      subtotal, discount, total, amount_paid, balance,
      dr_number, or_number, notes, import_key
    ) values (
      p_branch_id, v_customer, (v_row->>'date')::date, 'completed', v_method,
      v_total, 0, v_total, v_total, 0,
      'IMP-' || v_key, nullif(v_row->>'invoice', ''),
      'Sales-In import · SALES CEBU.xlsx · sheet ' || (v_row->>'sheet'), v_key
    )
    returning id into v_sale;

    for v_item in select * from jsonb_array_elements(v_row->'items')
    loop
      select id into v_sku from public.skus where barcode = v_item->>'barcode' limit 1;
      if v_sku is null then
        raise exception 'Unknown SKU barcode % on import key %', v_item->>'barcode', v_key;
      end if;
      insert into public.sale_items (
        sale_id, sku_id, sacks, price_per_sack, discount, line_total, source_description
      ) values (
        v_sale, v_sku,
        (v_item->>'bags')::numeric,
        (v_item->>'price')::numeric,
        0,
        round((v_item->>'bags')::numeric * (v_item->>'price')::numeric, 2),
        nullif(btrim(coalesce(v_item->>'desc', '')), '')
      );
      v_items := v_items + 1;
    end loop;

    insert into public.payments (sale_id, payment_date, amount, method, reference_no)
    values (v_sale, (v_row->>'date')::date, v_total, v_method, nullif(v_row->>'bank', ''));

    insert into public.delivery_receipts (sale_id, branch_id, dr_number, printed_at)
    values (v_sale, p_branch_id, 'IMP-' || v_key, now())
    on conflict (branch_id, dr_number) do nothing;

    v_sales := v_sales + 1;
  end loop;

  return jsonb_build_object('inserted_sales', v_sales, 'inserted_items', v_items, 'skipped', v_skipped);
end;
$fn$;

revoke all on function public.import_sales_ledger(uuid, jsonb) from public, anon, authenticated;

do $import$
declare
  v_branch uuid;
  v_result jsonb;
begin
  select id into v_branch
  from public.branches
  where id = '22222222-2222-2222-2222-222222222222'
     or lower(name) like '%cebu%'
  order by (id = '22222222-2222-2222-2222-222222222222') desc
  limit 1;

  if v_branch is null then
    raise exception 'Cebu branch not found — create it in Settings → Branches first';
